require __DIR__.'/bootstrap.php'; require_login(); $me=user();
$id=(int)($_GET['id']??0); $b=(int)require_branch(); $scope=is_admin()?'':' AND (s.branch_id='.$b.' OR s.to_branch_id='.$b.')';
$q=$pdo->prepare('SELECT s.*,a.name airline,a.code airline_code,b.name branch_name,u.name customer_name,u.phone customer_phone,u.account_no customer_account,u.email customer_email FROM shipments s JOIN airlines a ON a.id=s.airline_id JOIN branches b ON b.id=s.branch_id LEFT JOIN users u ON u.id=s.customer_id WHERE s.id=?'.$scope);$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Shipment not found.');}
$p=$pdo->prepare('SELECT p.*,u.name received_by FROM payments p JOIN users u ON u.id=p.received_by WHERE p.shipment_id=? ORDER BY p.paid_at DESC');$p->execute([$id]);$payments=$p->fetchAll();$title='Shipment · '.$s['awb'];require __DIR__.'/partials/header.php';
?>
