all><div class="fw-semibold"><?=e($s['fly_awb_no']?:'—')?></div></div><div class="card p-3 p-lg-4"><h2 class="h5 mb-3">People & status</h2><small class="text-secondary">Sender</small><div class="fw-semibold mb-3"><?=e($s['sender'])?><small class="d-block"><?=e($s['tell']?:'—')?></small></div><small class="text-secondary">Receiver</small><div class="fw-semibold mb-3"><?=e($s['receiver'])?></div><small class="text-secondary">Customer account</small><div class="mb-3"><?php if($s['customer_id']):?><?=e($s['customer_name'])?><?php if($s['customer_account']||$s['customer_phone']):?><small class="d-block text-secondary"><?=e(trim((($s['customer_account']??'').' · '.($s['customer_phone']??'')),' ·'))?></small><?php endif?><?php else:?><span class="text-secondary">Not linked</span><?php endif?></div><small class="text-secondary">Shipment status</small><div class="mb-3"><span class="status status-<?=strtolower(str_replace(' ','-',$s['status']))?>"><?=e($s['status'])?></span></div><small class="text-secondary">Balance</small><div class="h4 text-danger mb-0"><?=money($s['balance_mgq'])?></div></div></div></div>
